import type { ComponentProps, CSSProperties, KeyboardEvent, ReactNode } from "react";
import { useState } from "react";
import type { UserAskKnobStyle } from "@/components/control-ui/knob-contracts/user-ask-knobs";

export type UserAskAnswers = Record<string, string>;

export type UserAskProps = Omit<ComponentProps<"section">, "style"> & {
  children?: ReactNode;
  onComplete?: (answers: UserAskAnswers) => void;
  onDismiss?: () => void;
  style?: CSSProperties & UserAskKnobStyle;
};

export type UserAskQuestionEntry = {
  key: string;
  id: string;
  title: string;
  defaultValue?: string;
};

export type UserAskOptionEntry = {
  key: string;
  value: string;
  disabled?: boolean;
  /** Freeform options resolve to user's typed text instead of `value`. */
  freeform?: boolean;
};

function upsert<Entry extends { key: string }>(entries: Entry[], entry: Entry) {
  const index = entries.findIndex((existing) => existing.key === entry.key);
  if (index === -1) return [...entries, entry];
  const next = [...entries];
  next[index] = entry;
  return next;
}

export function useUserAsk({ onComplete, onDismiss }: Pick<UserAskProps, "onComplete" | "onDismiss">) {
  const [questions, setQuestions] = useState<UserAskQuestionEntry[]>([]);
  const [optionsByQuestion, setOptionsByQuestion] = useState<Record<string, UserAskOptionEntry[]>>({});
  // Explicit picks by option registration key; question's defaultValue is DERIVED in selectionFor, never copied here.
  const [selections, setSelections] = useState<Record<string, string>>({});
  const [freeformTexts, setFreeformTexts] = useState<Record<string, string>>({});
  const [requestedIndex, setRequestedIndex] = useState(0);

  // useState-once keeps identities stable; register upserts IN PLACE (prop change must not reorder numbering)
  // and unregister runs only at part unmount — combined effect cleanup would move updated entries to end.
  const [registerQuestion] = useState(() => (entry: UserAskQuestionEntry) => {
    setQuestions((previous) => upsert(previous, entry));
  });

  const [unregisterQuestion] = useState(() => (key: string) => {
    setQuestions((previous) => previous.filter((question) => question.key !== key));
  });

  const [registerOption] = useState(() => (questionId: string, entry: UserAskOptionEntry) => {
    setOptionsByQuestion((previous) => ({ ...previous, [questionId]: upsert(previous[questionId] ?? [], entry) }));
  });

  const [unregisterOption] = useState(() => (questionId: string, key: string) => {
    setOptionsByQuestion((previous) => ({
      ...previous,
      [questionId]: (previous[questionId] ?? []).filter((option) => option.key !== key),
    }));
  });

  const activeIndex = questions.length === 0 ? 0 : Math.min(requestedIndex, questions.length - 1);
  const activeQuestion = questions[activeIndex];

  function optionsFor(questionId: string) {
    return optionsByQuestion[questionId] ?? [];
  }

  function selectionFor(questionId: string) {
    const explicit = selections[questionId];
    if (explicit) return explicit;
    const defaultValue = questions.find((question) => question.id === questionId)?.defaultValue;
    if (defaultValue === undefined) return undefined;
    return optionsFor(questionId).find((option) => !option.freeform && option.value === defaultValue)?.key;
  }

  function isSelected(questionId: string, optionKey: string) {
    return selectionFor(questionId) === optionKey;
  }

  function select(questionId: string, optionKey: string) {
    setSelections((previous) => ({ ...previous, [questionId]: optionKey }));
  }

  function freeformTextFor(questionId: string) {
    return freeformTexts[questionId] ?? "";
  }

  function setFreeformText(questionId: string, text: string) {
    setFreeformTexts((previous) => ({ ...previous, [questionId]: text }));
  }

  function answerFor(questionId: string) {
    const selectedKey = selectionFor(questionId);
    const option = optionsFor(questionId).find((entry) => entry.key === selectedKey);
    if (!option) return undefined;
    if (!option.freeform) return option.value;
    const text = freeformTextFor(questionId).trim();
    return text.length > 0 ? text : undefined;
  }

  const canContinue = activeQuestion !== undefined && answerFor(activeQuestion.id) !== undefined;
  const isLastQuestion = activeIndex === questions.length - 1;

  function goTo(index: number) {
    setRequestedIndex(Math.max(0, Math.min(index, questions.length - 1)));
  }

  function resolveAnswers() {
    const answers: UserAskAnswers = {};
    for (const question of questions) {
      const answer = answerFor(question.id);
      if (answer !== undefined) answers[question.id] = answer;
    }
    return answers;
  }

  function advance() {
    if (!canContinue) return;
    if (isLastQuestion) onComplete?.(resolveAnswers());
    else goTo(activeIndex + 1);
  }

  function dismiss() {
    onDismiss?.();
  }

  function moveSelection(delta: number) {
    if (!activeQuestion) return;
    const options = optionsFor(activeQuestion.id);
    if (!options.some((option) => !option.disabled)) return;
    const currentKey = selectionFor(activeQuestion.id);
    const currentIndex = options.findIndex((option) => option.key === currentKey);
    let start = currentIndex;
    if (currentIndex === -1) start = delta > 0 ? -1 : 0;
    for (let step = 1; step <= options.length; step += 1) {
      const candidate = options[(start + delta * step + options.length * step) % options.length];
      if (!candidate.disabled) {
        select(activeQuestion.id, candidate.key);
        return;
      }
    }
  }

  function selectDigit(digit: number) {
    if (!activeQuestion) return;
    const option = optionsFor(activeQuestion.id)[digit - 1];
    if (option && !option.disabled) select(activeQuestion.id, option.key);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLElement>) {
    if (event.defaultPrevented) return;
    if (event.key === "Escape") {
      event.preventDefault();
      dismiss();
      return;
    }
    if (event.key === "Enter") {
      // Enter always means "continue" (even from option or freeform input), matching CLI ask flows.
      event.preventDefault();
      advance();
      return;
    }
    // Inside freeform input, digits and arrows must keep typing/caret behavior.
    if (event.target instanceof HTMLElement && event.target.closest("input, textarea, [contenteditable]")) return;
    if (event.key === "ArrowDown") {
      event.preventDefault();
      moveSelection(1);
      return;
    }
    if (event.key === "ArrowUp") {
      event.preventDefault();
      moveSelection(-1);
      return;
    }
    if (/^[1-9]$/.test(event.key)) {
      // preventDefault: selecting freeform option moves focus into its input before keypress — without this digit would be typed there.
      event.preventDefault();
      selectDigit(Number(event.key));
    }
  }

  return {
    questions,
    activeIndex,
    activeQuestion,
    canContinue,
    isLastQuestion,
    registerQuestion,
    unregisterQuestion,
    registerOption,
    unregisterOption,
    optionsFor,
    selectionFor,
    isSelected,
    select,
    freeformTextFor,
    setFreeformText,
    answerFor,
    resolveAnswers,
    goTo,
    advance,
    dismiss,
    handleKeyDown,
  };
}

@layer components {
  :where([data-control-family="button"][data-user-ask-dismiss="true"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="kbd"][data-user-ask-submit-kbd="true"]) {
    background: oklch(from var(--primary-foreground) l c h / 0.15);
    color: var(--primary-foreground);
    box-shadow: inset 0 0 0 1px oklch(from var(--primary-foreground) l c h / 0.25);
  }

  :where([data-control-family="user-ask"][data-slot="option-input"]) {
    font-weight: var(--font-weight-medium);
    outline-style: none;
  }

  :where([data-control-family="user-ask"][data-slot="option-indicator"]) {
    font-weight: var(--font-weight-medium);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="user-ask"][data-slot="option-description"]) {
    font-weight: var(--font-weight-normal);
  }

  :where([data-control-family="user-ask"][data-slot="recommended"]) {
    font-weight: var(--font-weight-normal);
  }

  :where([data-control-family="user-ask"][data-slot="option-label"]) {
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="user-ask"][data-slot="title"]) {
    font-weight: var(--font-weight-semibold);
  }

  :where([data-control-family="user-ask"][data-slot="root"]) {
    outline-style: none;
  }

  :where([data-control-family="user-ask"][data-slot="pagination-count"]) {
    font-variant-numeric: tabular-nums;
  }
}

@layer components {
  :where([data-control-family="user-ask"][data-slot="root"]) {
    --cui-user-ask-background: oklch(from var(--card) l c h / 0.9);
    --cui-user-ask-border-color: var(--border);
    --cui-user-ask-foreground: var(--foreground);
    --cui-user-ask-radius: var(--radius-field);
    --cui-user-ask-shadow: var(--shadow-md);
    --cui-user-ask-indicator-background: var(--muted);
    --cui-user-ask-indicator-foreground: var(--muted-foreground);
    --cui-user-ask-input-background: transparent;
    --cui-user-ask-input-foreground: var(--foreground);
    --cui-user-ask-option-hover-background: oklch(from var(--muted) l c h / 0.5);
    --cui-user-ask-option-radius: var(--radius-popup-item);
    --cui-user-ask-option-selected-background: oklch(from var(--muted) l c h / 0.7);
    border: 1px solid var(--cui-user-ask-border-color);
    border-radius: var(--cui-user-ask-radius);
    background: var(--cui-user-ask-background);
    color: var(--cui-user-ask-foreground);
    box-shadow:
      inset 0 0 0 1px oklch(from var(--foreground) l c h / 0.04),
      var(--cui-user-ask-shadow);
    backdrop-filter: blur(var(--backdrop-blur-popover));
    font-size: var(--text-body);
    transition-property: opacity, translate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  @starting-style {
    :where([data-control-family="user-ask"][data-slot="root"]) {
      opacity: 0;
      translate: 0 0.5rem;
    }
  }

  :where([data-control-family="user-ask"][data-slot="title"]) {
    color: var(--foreground);
    font-size: var(--text-sm);
  }

  :where([data-control-family="user-ask"][data-slot="pagination"]) {
    color: var(--muted-foreground);
    font-size: var(--text-micro);
  }

  :where([data-control-family="user-ask"][data-slot="option"]) {
    border-radius: var(--cui-user-ask-option-radius);
    font-size: var(--text-sm);
    transition-property: background-color, box-shadow;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
    text-align: left;
  }

  :where([data-control-family="user-ask"][data-slot="option"][data-selected]) {
    background: var(--cui-user-ask-option-selected-background);
  }

  @media (hover: hover) {
    :where([data-control-family="user-ask"][data-slot="option"]:hover) {
      background: var(--cui-user-ask-option-hover-background);
    }
  }

  :where([data-control-family="user-ask"][data-slot="option"]:disabled) {
    opacity: 0.5;
  }

  :where([data-control-family="user-ask"][data-slot="option-indicator"]) {
    border-radius: var(--radius-control);
    background: var(--cui-user-ask-indicator-background);
    color: var(--cui-user-ask-indicator-foreground);
    font-size: var(--text-micro);
  }

  :where([data-control-family="user-ask"][data-slot="option-indicator"][data-selected]) {
    background: var(--primary);
    color: var(--primary-foreground);
  }

  :where([data-control-family="user-ask"][data-slot="option-label"]) {
    color: var(--foreground);
  }

  :where([data-control-family="user-ask"]:is([data-slot="recommended"], [data-slot="option-description"], [data-slot="freeform-label"])) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="user-ask"][data-slot="option-description"]) {
    font-size: var(--text-caption);
  }

  :where([data-control-family="user-ask"][data-slot="option-input"]) {
    --_user-ask-input-placeholder-paint: var(--muted-foreground);
    border: 0;
    background: var(--cui-user-ask-input-background);
    color: var(--cui-user-ask-input-foreground);
  }

  :where([data-control-family="user-ask"][data-slot="option-input"])::placeholder {
    color: var(--_user-ask-input-placeholder-paint);
    font-weight: 400;
  }
}

